{
  "missing_information": [
    {
      "category": "Tool Selection Logic",
      "gap": "No criteria are given for how a specific measurement tool is chosen for a given wafer",
      "why_it_matters": "Without knowing the selection logic, it is impossible to model the decision gateway or assess whether tool assignment can be automated"
    },
    {
      "category": "Preparation Steps per Tool",
      "gap": "The preparation activities that differ by tool are not described in any detail",
      "why_it_matters": "Each distinct preparation sequence represents a separate process path; missing this detail prevents accurate process modeling and identification of automation candidates"
    },
    {
      "category": "Measurement Step Variants",
      "gap": "The actual measurement actions performed on each tool are unspecified",
      "why_it_matters": "Understanding what each tool does during measurement is required to identify redundant steps, quality checkpoints, and automation potential"
    },
    {
      "category": "Result Recording Method",
      "gap": "It is unclear how the engineer records the result—manually into a system, via automated data capture, or on paper—and what data fields are captured",
      "why_it_matters": "The recording method directly determines automation feasibility and data quality risks at the final step"
    },
    {
      "category": "Error and Rework Handling",
      "gap": "No information is provided about what happens when a measurement is out of specification or a tool malfunctions",
      "why_it_matters": "Exception paths are frequently the most time-consuming and error-prone parts of a workflow and must be modeled to assess end-to-end automation"
    },
    {
      "category": "Handoff and Sequencing",
      "gap": "It is unclear whether the wafer must pass through any verification or approval step between measurement and result recording, or whether multiple tools are used sequentially on the same wafer",
      "why_it_matters": "Unmodeled handoffs or sequential tool usage would change the process structure and the number of automation integration points"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What determines which measurement tool is selected for a given wafer—is it based on wafer type, lot recipe, engineer judgment, tool availability, or some combination of these factors?",
      "targets": ["Tool Selection Logic"]
    },
    {
      "id": "Q2",
      "question": "For each tool variant, what are the specific preparation steps the engineer or system must perform before the measurement can begin?",
      "targets": ["Preparation Steps per Tool"]
    },
    {
      "id": "Q3",
      "question": "What actions constitute the measurement step on each tool—for example, does the engineer manually position the wafer, initiate a software routine, or is the measurement fully automated once the wafer is loaded?",
      "targets": ["Measurement Step Variants"]
    },
    {
      "id": "Q4",
      "question": "How does the engineer record the measurement result—is it entered manually into a data system, automatically exported from the tool's software, or documented on a physical form?",
      "targets": ["Result Recording Method"]
    },
    {
      "id": "Q5",
      "question": "What happens when a measurement result falls outside the acceptable specification range—does the wafer get re-measured, routed to a rework step, or escalated to a supervisor?",
      "targets": ["Error and Rework Handling"]
    },
    {
      "id": "Q6",
      "question": "Is a single tool always used per wafer per workflow instance, or can the same wafer be measured by multiple tools in sequence before the result is recorded?",
      "targets": ["Handoff and Sequencing"]
    }
  ]
}
